UPDATE seo_regions SET
  hero_text = '에코델타시티에서 이음치과까지 자차 8분. 강서구 최신 미래 신도시 거주민을 위한 디지털 치과 — CBCT·3D 진단·디지털 가이드 임플란트 보유.',
  content = '<p><strong>에코델타시티 치과 — 부산 강서구 에코델타시티에서 이음치과의원까지 자차 8분 거리입니다.</strong></p><p>에코델타시티는 부산광역시가 추진하는 미래형 친환경 스마트 신도시로, 2024년부터 본격 입주가 시작되며 향후 5년 내 30,000세대 규모로 성장할 예정인 차세대 거주 지역입니다. 젊은 가족 단위 거주민, IT 종사자, 신혼부부가 주로 입주합니다.</p><p><strong>에코델타시티 신도시 거주민의 진료 트렌드:</strong></p><ul><li><strong>인비절라인·투명교정</strong> — 직장인이 티 안 나게 교정</li><li><strong>심미 라미네이트·글로우네이트</strong> — 결혼 준비·연애 세대</li><li><strong>소아 검진·실란트</strong> — 첫 자녀 가족 다수</li><li><strong>디지털 임플란트</strong> — 부모님 케어 30~40대</li></ul><p><strong>이음치과가 에코델타 신도시에 잘 맞는 이유:</strong></p><p>① CBCT(3D CT) 보유 — 정확한 진단으로 재수술 위험 최소화<br>② 디지털 가이드 시스템 — 오차 0.1mm 정밀 임플란트<br>③ 인비절라인 다이아몬드 제공자 — 부산 일대 최상위 등급<br>④ 글로우네이트 라미네이트 전문 — 자연스러운 치아 색감</p><p><strong>오시는 방법:</strong> 에코델타로 → 명지국제대로 → 명지국제8로 265번지, 자차 8분. 대중교통: 강서20번·강서마을버스 (약 15~20분). 2시간 무료 주차.</p>',
  nearby_areas = '[{"name":"명지동","slug":"myeongji"},{"name":"명지오션시티","slug":"myeongji-ocean"},{"name":"대저동","slug":"daejeo"},{"name":"강동동","slug":"gangdong"},{"name":"가락동","slug":"garak"}]'
