-- 7. 대저동
UPDATE seo_regions SET
  hero_text = '대저동·대저1동·대저2동 거주민이 자차 12분 거리에서 받는 정밀 치과 진료. 김해공항 인근 거주민도 편리합니다.',
  content = '<p><strong>대저동 치과 — 대저동에서 이음치과의원까지 자차 12분, 강동동·명지동을 거치는 명지국제대로 코스로 도착합니다.</strong></p><p>대저동은 부산 강서구의 북동쪽, 김해국제공항 인근에 위치한 광역 행정동입니다. 대저1동·대저2동으로 구분되며 신구도로변·공항로·낙동대로 등 주요 교통 축 인근으로 거주민이 분포합니다. 공항 종사자, 항공물류 관련 가족, 그리고 김해와 인접한 거주민이 많은 특징이 있습니다.</p><p><strong>대저동 거주민의 진료 요구:</strong></p><ul><li><strong>임플란트·풀임플란트</strong> — 40~60대 무치악 케이스</li><li><strong>잇몸치료·치주염</strong> — 흡연·스트레스 케어</li><li><strong>심미보철·올세라믹</strong> — 자연스러운 치아 마감</li><li><strong>가족 진료</strong> — 자녀 충치예방 + 부모 임플란트</li></ul><p><strong>오시는 길:</strong></p><p>① 자차: 낙동대로 → 명지국제대로 → 명지국제8로 265 (약 12분)<br>② 대중교통: 대저역에서 강서11번·강서20번 환승 (약 30분)<br>③ 김해공항 인근: 공항로 → 명지국제대로 (약 15분)</p><p>이음치과는 대저동 거주민의 통원 거리를 고려해 사전 예약 시 대기시간 최소화 시스템을 운영합니다. 한 번 방문에 진단·시술·후속 케어까지 통합 진행 가능합니다. ☎ 051-206-5888.</p>',
  nearby_areas = '[{"name":"강동동","slug":"gangdong"},{"name":"가락동","slug":"garak"},{"name":"에코델타시티","slug":"eco-delta"},{"name":"명지동","slug":"myeongji"}]'
